% Define the differential equation
f = @(x,y) -2 * x.^3 + 12 * x.^2 - 20 * x + 8.5;

% Initial conditions
x0 = 0;
y0 = 1;
X_end = 5;   % Final x-value

% Step sizes to compare
h_values = [0.5, 0.25, 0.1, 0.05];

% Colors for plotting
colors = {'r','b','g','m'};

figure;
hold on;

% Loop over step sizes
for k = 1:length(h_values)
    h = h_values(k);
    N = round((X_end - x0)/h);

    % Initialize arrays
    x = zeros(1, N+1);
    y = zeros(1, N+1);

    % Set initial values
    x(1) = x0;
    y(1) = y0;

    % Runge-Kutta 4th Order Method
    for i = 1:N
        k1 = h * f(x(i), y(i));
        k2 = h * f(x(i) + h/2, y(i) + k1/2);
        k3 = h * f(x(i) + h/2, y(i) + k2/2);
        k4 = h * f(x(i) + h, y(i) + k3);

        y(i+1) = y(i) + (k1 + 2*k2 + 2*k3 + k4)/6;
        x(i+1) = x(i) + h;
    end

    % Plot this solution
    plot(x, y, 'Color', colors{k}, 'DisplayName', sprintf('h = %.3f', h));
end

% Finalize plot
title("Runge-Kutta 4th Order Solutions with Different Step Sizes");
xlabel('x');
ylabel('y');
grid on;
legend show;
hold off;

% Define the differential equation as a function
f = @(x,y) -2 * x^3 + 12 * x^2 - 20 * x + 8.5;

% Define the exact solution
exact_eqn = @(x) -0.5 * x^4 + 4 * x^3 - 10 * x^2 + 8.5 * x + 1;

% Step sizes to compare
h_values = [0.5, 0.25, 0.1, 0.05];

% Initial conditions
x0 = 0;
y0 = 1;
X_end = 5;   % final x value

% Colors for plotting
colors = {'r','b','g','m'};

figure;
hold on;

% Loop over different step sizes
for k = 1:length(h_values)
    h = h_values(k);
    N = round((X_end - x0)/h);

    % Initialize arrays
    x = zeros(1, N+1);
    y = zeros(1, N+1);

    % Set initial values
    x(1) = x0;
    y(1) = y0;

    % Euler's Method
    for i = 1:N
        x(i+1) = x(i) + h;
        y(i+1) = y(i) + h * f(x(i), y(i));
    end

    % Plot this solution
    plot(x, y, 'Color', colors{k}, 'DisplayName', sprintf('h = %.3f', h));
end

% Plot exact solution
x_exact = linspace(x0, X_end, 200);
y_exact = exact_eqn(x_exact);
plot(x_exact, y_exact, 'k--', 'LineWidth', 1.5, 'DisplayName', 'Exact');

% Finalize plot
title("Euler's Method for Different Step Sizes");
xlabel('x');
ylabel('y');
grid on;
legend show;
hold off;

% Define the differential equation as a function
f = @(x,y) -2 * x^3 + 12 * x^2 - 20 * x + 8.5;

% Define the functions for error calculations
exact_eqn = @(x) -0.5 * x^4 + 4 * x^3 - 10 * x^2 + 8.5 * x + 1;
f1 = @(x,h) (-6 * x^2 + 24 * x - 20) * (h^2 / 2);
f2 = @(x,h) (-12 * x + 24) * (h^3 / 6);
f3 = @(h) (-12) * (h^4 / 24);

% Define the initial conditions
x0 = 0; % Initial x
y0 = 1; % Initial condition
h = 0.5; % x increment step

% Define the number of x steps
N = 10;

% Initialize arrays for storing the solutions and errors
x = zeros(1, N+1);
y = zeros(1, N+1);
exact_soln = zeros(1, N+1);
global_error = zeros(1, N+1);
local_error = zeros(1, N+1);

% Set the initial values
x(1) = x0;
y(1) = y0;
exact_soln(1) = exact_eqn(x0);

% Compute the solutions and errors using Euler's Method
for i = 1:N
    x(i+1) = x(i) + h;
    y(i+1) = y(i) + h * f(x(i), y(i));

    exact_soln(i+1) = exact_eqn(x(i+1));
    global_error(i+1) = abs(exact_soln(i+1) - y(i+1)) / exact_soln(i+1) * 100;
    local_error(i+1) = abs(f1(x(i), h) + f2(x(i), h) + f3(h)) / exact_soln(i+1) * 100;
end

% Print the results
disp('x       True Soln.    Approx. Soln.    Global Error(%)    Local Error(%)');
for i = 1:N+1
    fprintf('%.3f    %.3f        %.3f            %.3f            %.3f\n', ...
            x(i), exact_soln(i), y(i), global_error(i), local_error(i));
end

% Plot the results
figure;
plot(x, y, 'bo-', 'LineWidth', 1.5); hold on;
plot(x, exact_soln, 'r*-', 'LineWidth', 1.5);
title("Comparison of Euler's Method and True Solution");
xlabel('x');
ylabel('y');
legend('Euler Method', 'True Solution');
grid on;
